import csv, re, math, statistics
from datetime import datetime, timezone
from collections import defaultdict

path='/app/dataset/data.csv'
num_re = r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)'

def parse_amount(s, paren_mode='enclosed', cr_mode='token'):
    if s is None: return math.nan
    t = s.strip()
    if t == '': return math.nan
    if cr_mode == 'token':
        cr = re.search(r'(?<![A-Za-z0-9])CR(?![A-Za-z0-9])', t) is not None
    else:
        cr = 'CR' in t
    if paren_mode == 'enclosed':
        par = t.startswith('(') and t.endswith(')')
    elif paren_mode == 'any':
        par = '(' in t or ')' in t
    else:
        par = False
    neg = cr or par or ('-' in t)
    u = re.sub(r'C[12]', '', t)
    cleaned = ''.join(ch for ch in u if ch.isdigit() or ch in ',.')
    if not any(ch.isdigit() for ch in cleaned): return math.nan
    dot_positions = [i for i, ch in enumerate(cleaned) if ch == '.']
    comma_positions = [i for i, ch in enumerate(cleaned) if ch == ',']
    def with_decimal(pos):
        parts=[]
        for i,ch in enumerate(cleaned):
            if ch.isdigit(): parts.append(ch)
            elif i == pos: parts.append('.')
            # other separators dropped
        return ''.join(parts)
    if dot_positions and comma_positions:
        pos = max(dot_positions[-1], comma_positions[-1])
        out = with_decimal(pos)
    elif dot_positions or comma_positions:
        positions = dot_positions or comma_positions
        sep = '.' if dot_positions else ','
        pos = positions[-1]
        digits_after = len(cleaned) - pos - 1
        if digits_after == 2:
            out = with_decimal(pos)
        else:
            out = cleaned.replace(sep, '')
    else:
        out = cleaned
    try:
        val = float(out)
    except ValueError:
        return math.nan
    return -val if neg else val

def parse_notes(notes):
    n = notes or ''
    m = re.search(r'\bitems=([+-]?\d+)\b', n, flags=re.I)
    items = int(m.group(1)) if m else None
    m = re.search(r'\badj=(' + num_re + r')%', n, flags=re.I)
    adj = float(m.group(1))/100.0 if m else 0.0
    m = re.search(r'\bfee=(' + num_re + r')\b', n, flags=re.I)
    fee = float(m.group(1)) if m else 0.0
    waive = re.search(r'\bwaive=true\b', n, flags=re.I) is not None
    return items, adj, fee, waive

def parse_time(t):
    if not t: return None
    # 2025-09-11T04:50:00Z
    return datetime.strptime(t, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)

def calc(channel_strip=True, paren_mode='enclosed', dedup_before_filter=True, cr_mode='token'):
    rows=[]
    with open(path, newline='') as f:
        for order,row in enumerate(csv.DictReader(f)):
            base = parse_amount(row['amount_str'], paren_mode=paren_mode, cr_mode=cr_mode)
            items, adj, fee, waive = parse_notes(row['notes'])
            if math.isnan(base):
                net = math.nan
            else:
                net = base*(1+adj)+fee
                if waive:
                    net = 0.0
            event_dt = parse_time(row['event_time'])
            rows.append({**row, 'order':order, 'base':base, 'items':items, 'adj':adj, 'fee':fee, 'waive':waive, 'net':net, 'event_dt':event_dt, 'real_net':math.isfinite(net)})
    start=datetime(2025,10,1,0,0,0,tzinfo=timezone.utc)
    end=datetime(2025,12,31,23,59,59,tzinfo=timezone.utc)
    def keep_filter(r):
        if r['event_dt'] is None: return False
        if not (start <= r['event_dt'] <= end): return False
        ch = r['channel'].lower()
        if channel_strip: ch = r['channel'].strip().lower()
        if ch == 'phone': return False
        if not math.isfinite(r['net']): return False
        return True
    if dedup_before_filter:
        # choose per record_id: latest event_time, missing earliest; tie real net; tie earlier order
        best={}
        for r in rows:
            key=r['record_id']
            def sortkey(x):
                # latest max; missing min
                return (x['event_dt'] if x['event_dt'] is not None else datetime.min.replace(tzinfo=timezone.utc), x['real_net'], -x['order'])
            if key not in best or sortkey(r) > sortkey(best[key]):
                best[key]=r
        rows=list(best.values())
        rows=[r for r in rows if keep_filter(r)]
    else:
        rows=[r for r in rows if keep_filter(r)]
        best={}
        for r in rows:
            key=r['record_id']
            def sortkey(x):
                return (x['event_dt'] if x['event_dt'] is not None else datetime.min.replace(tzinfo=timezone.utc), x['real_net'], -x['order'])
            if key not in best or sortkey(r) > sortkey(best[key]):
                best[key]=r
        rows=list(best.values())
    groups=defaultdict(list)
    for r in rows:
        month=r['event_dt'].strftime('%Y-%m')
        r['month']=month
        groups[(r['region'],month)].append(r)
    for g,rs in groups.items():
        vals=[r['net'] for r in rs]
        med=statistics.median(vals)
        mad=statistics.median([abs(v-med) for v in vals])
        for r in rs:
            z=0.0 if mad == 0 else 0.6745*(r['net']-med)/mad
            r['robust_z']=z
            r['abs_z']=abs(z)
            items_eff=r['items'] if r['items'] is not None else 1
            items_eff=max(items_eff,1)
            r['score']=abs(z)*math.log1p(items_eff)
    rows.sort(key=lambda r:(-r['score'], -r['abs_z'], -r['event_dt'].timestamp(), r['record_id']))
    return rows

variants=[]
for channel_strip in [True,False]:
    for paren_mode in ['enclosed','any']:
        for dedup_before_filter in [True,False]:
            rows=calc(channel_strip=channel_strip, paren_mode=paren_mode, dedup_before_filter=dedup_before_filter)
            variants.append((channel_strip,paren_mode,dedup_before_filter, [r['record_id'] for r in rows[:10]], rows[:10], len(rows)))
for channel_strip, paren_mode, dbf, top, rows, n in variants:
    print('\nvariant strip=%s paren=%s dedup_before=%s n=%s' % (channel_strip,paren_mode,dbf,n))
    print(top)
    for i,r in enumerate(rows[:12],1):
